class CandidateReason(BaseModel):
    """
    R5 포함 규칙. 모든 후보는 사건 similarity_threshold 이상. time_feasible=true: 기본 기준 이상이면 포함. time_feasible=false: out_of_filter_threshold가 있고 similarity >= max(similarity_threshold, out_of_filter_threshold)일 때만 포함, TIME_REVIEW_REQUIRED. time_feasible=null(경로를 찾지 못해 판정 불가): 기본 기준 이상이면 포함, MANUAL_REVIEW_REQUIRED와 ROUTE_UNKNOWN. 시간 조건은 최대 보행 속도 기반 최소 이동 시간으로 판단한다(고정 여유 시간·확인 요청 기준 없음). 방향 불일치 등은 전용 코드 없이 순위와 summary에만 반영한다.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    similarity: Annotated[
        float,
        Field(
            description="L2 정규화 임베딩의 코사인 유사도. 동일인 확률이 아니다.",
            ge=-1.0,
            le=1.0,
        ),
    ]
    threshold: Annotated[
        float,
        Field(
            description="설정용 유사도 임계값. 점수 자체의 범위는 -1~1이며 운영 임계값은 0~1로 제한하는 제안.",
            ge=0.0,
            le=1.0,
        ),
    ]
    model_name: str
    time_feasible: bool | None
    minimum_travel_time_s: MinimumTravelTimeS | None
    available_time_s: AvailableTimeS | None
    reason_codes: list[
        Literal[
            "APPEARANCE_MATCH",
            "TIME_FEASIBLE",
            "ROUTE_UNKNOWN",
            "TIME_REVIEW_REQUIRED",
            "MANUAL_REVIEW_REQUIRED",
        ]
    ]
    summary: str


