class SystemSettings(BaseModel):
    """
    프리셋 유형 중복 금지. 범위 비율은 r1<r2<r3=1인 누적 영역. 기본값<high. 미설정 값은 null이며 해당 계산/감시 차단. 임의 운영 수치 확정 안 함. out_of_filter_threshold(R5): 초기값 null=시간 조건 밖 후보 예외 허용 안 함. PATCH 생략=유지, null=해제. 후보 검색에만 적용하고 출현 알림 기준에는 적용하지 않는다.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    walking_speed_presets: Annotated[
        list[WalkingSpeedPreset], Field(max_length=4, min_length=4)
    ]
    default_similarity_threshold: DefaultSimilarityThreshold | None
    alert_high_threshold: AlertHighThreshold | None
    area_level_ratios: Annotated[
        list[AreaLevelRatio], Field(max_length=3, min_length=3)
    ]
    area_buffer_m: AreaBufferM | None
    max_upload_bytes: MaxUploadBytes | None
    version: Annotated[int, Field(ge=1)]
    updated_at: Annotated[
        AwareDatetime,
        Field(
            description="시간대 필수 RFC3339. 저장 UTC, 응답 Z 또는 오프셋. 시간대 없는 값은 422."
        ),
    ]
    out_of_filter_threshold: OutOfFilterThreshold | None


class SystemSettingsPatch(BaseModel):
    """
    기본 유사도는 새 사건에만 적용. 속도·구역 비율은 다음 계산에 반영. high를 낮춰 충돌하는 기존 감시 사건이 생기면 409와 사건 ID 반환. 기존 사건 mid는 변경하지 않음.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    walking_speed_presets: Annotated[
        list[WalkingSpeedPreset] | None, Field(max_length=4, min_length=4)
    ] = None
    default_similarity_threshold: Annotated[
        float | None,
        Field(
            description="설정용 유사도 임계값. 점수 자체의 범위는 -1~1이며 운영 임계값은 0~1로 제한하는 제안.",
            ge=0.0,
            le=1.0,
        ),
    ] = None
    alert_high_threshold: Annotated[
        float | None,
        Field(
            description="설정용 유사도 임계값. 점수 자체의 범위는 -1~1이며 운영 임계값은 0~1로 제한하는 제안.",
            ge=0.0,
            le=1.0,
        ),
    ] = None
    area_level_ratios: Annotated[
        list[AreaLevelRatio] | None, Field(max_length=3, min_length=3)
    ] = None
    area_buffer_m: Annotated[float | None, Field(gt=0.0)] = None
    max_upload_bytes: Annotated[int | None, Field(ge=1)] = None
    expected_version: Annotated[int, Field(ge=1)]
    out_of_filter_threshold: OutOfFilterThreshold | None = None


