class PendingCount(RootModel[int]):
    root: Annotated[
        int,
        Field(
            description="latest_search가 done이고 stale=false일 때, 그 검색 후보 중 유효한 active 판단이 없는 후보 수. confirmed/rejected/deferred는 모두 판단 완료.",
            ge=0,
        ),
    ]


class CaseSummary(BaseModel):
    """
    R1. pending_count=null은 검색이 없거나 queued/running/failed/stale인 경우이며 후보 0개와 구분한다. 현재 사용자가 접근할 수 있는 사건 데이터만 집계.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    confirmed_count: Annotated[
        int,
        Field(
            description="verdict=confirmed, status=active, needs_reconfirmation=false인 판단 수. 트랙렛·출현 알림 출처 모두 포함.",
            ge=0,
        ),
    ]
    pending_count: PendingCount | None


